local function C_3()
	local script = LMG2L["LocalScript_3"];
	-- LocalScript Draggable Frame - PC + Mobile (toque e arrastar)

	-- Coloca dentro do Frame que tu quer mover



	local UserInputService = game:GetService("UserInputService")

	local TweenService = game:GetService("TweenService")



	local frame = script.Parent  -- o Frame que vai ser arrastado

	local dragging = false

	local dragInput = nil

	local dragStart = nil

	local startPos = nil



	-- FunÃ§Ã£o pra iniciar o drag (mouse ou toque)

	local function updateInput(input)

	    local delta = input.Position - dragStart

	    local newPos = UDim2.new(

	        startPos.X.Scale,

	        startPos.X.Offset + delta.X,

	        startPos.Y.Scale,

	        startPos.Y.Offset + delta.Y

	    )

	    frame.Position = newPos

	end



	frame.InputBegan:Connect(function(input)

	    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then

	        dragging = true

	        dragStart = input.Position

	        startPos = frame.Position



	        input.Changed:Connect(function()

	            if input.UserInputState == Enum.UserInputState.End then

	                dragging = false

	            end

	        end)

	    end

	end)



	frame.InputChanged:Connect(function(input)

	    if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then

	        dragInput = input

	    end

	end)



	UserInputService.InputChanged:Connect(function(input)

	    if input == dragInput and dragging then

	        updateInput(input)

	    end

	end)



	-- Opcional: animaÃ§Ã£o suave ao soltar (pra ficar bonito)

	frame.InputEnded:Connect(function(input)

	    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then

	        dragging = false

	        -- Tween suave pra "parar" (opcional, comenta se nÃ£o quiser)

	        local tweenInfo = TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

	        TweenService:Create(frame, tweenInfo, {Position = frame.Position}):Play()

	    end

	end)



	print("Frame draggable ativado! (PC + Mobile)")	
end;
task.spawn(C_3);

