local function C_5()
	local script = LMG2L["LocalScript_5"];

	-- SKYBOX SCRIPT BY BIPOLARKIDD:) - adaptado com ID 13337209605 e spin tumbling

	script.Parent.MouseButton1Click:Connect(function()

	    local player = game.Players.LocalPlayer
	    local skyid = "13337209605"
	    local remote = nil

	    spawn(function()
	        repeat task.wait(0.2)
	            for _, tool in pairs(player.Character:GetChildren()) do
	                if tool:IsA("Tool") and tool:FindFirstChild("SyncAPI") and tool.SyncAPI:FindFirstChild("ServerEndpoint") then
	                    remote = tool.SyncAPI.ServerEndpoint
	                    break
	                end
	            end
	            if not remote then
	                for _, tool in pairs(player.Backpack:GetChildren()) do
	                    if tool:IsA("Tool") and tool:FindFirstChild("SyncAPI") and tool.SyncAPI:FindFirstChild("ServerEndpoint") then
	                        remote = tool.SyncAPI.ServerEndpoint
	                        break
	                    end
	                end
	            end
	        until remote
	    end)

	    repeat task.wait() until remote

	    local function invoke(args)
	        pcall(function() remote:InvokeServer(unpack(args)) end)
	    end

	    if workspace:FindFirstChild("sky") then invoke({"Remove", {[1] = workspace.sky}}) end
	    wait(0.3)

	    local character = player.Character or player.CharacterAdded:Wait()
	    local hrp = character:FindFirstChild("HumanoidRootPart") or character:WaitForChild("HumanoidRootPart")

	    invoke({"CreatePart", "Normal", CFrame.new(hrp.Position), workspace})
	    wait(0.4)

	    local tempPart = workspace:FindFirstChild("Part")
	    if tempPart then invoke({"SetName", {[1] = tempPart}, "sky"}) end

	    local sky = workspace:FindFirstChild("sky")
	    if sky then
	        invoke({"SyncCollision", {[1] = {["Part"] = sky, ["CanCollide"] = false}}})
	        invoke({"SetLocked", {[1] = sky}, true})
	        invoke({"CreateMeshes", {[1] = {["Part"] = sky}}})
