	        invoke({"SyncMesh", {[1] = {["Part"] = sky, ["TextureId"] = "rbxassetid://"..skyid}}})

	        -- SPIN TUMBLING SUAVE
	        spawn(function()
	            local RunService = game:GetService("RunService")
	            local speed = 0.8
	            while task.wait() do
	                if sky and sky.Parent then
	                    local delta = RunService.Heartbeat:Wait()
	                    local rotateX = CFrame.Angles(math.rad(speed * delta * 30), 0, 0)
	                    local rotateY = CFrame.Angles(0, math.rad(speed * delta * 40), 0)
	                    local rotateZ = CFrame.Angles(0, 0, math.rad(speed * delta * 20))
	                    local newCF = sky.CFrame * rotateX * rotateY * rotateZ
	                    invoke({"SyncMove", {[1] = {["Part"] = sky, ["CFrame"] = newCF}}})
	                end
	            end
	        end)
